//! `ContentBlacklist` contract ABI bindings (ADR 011 § Content Takedown).
//!
//! Generated by the `alloy::sol!` macro from the Solidity surface in
//! `contracts/src/ContentBlacklist.sol`. The node's blacklist sync
//! (`decdn-node::blacklist_watcher`) builds its deny index from the
//! enumeration views at boot and then follows the append-only mutation ledger
//! (`mutationCount`, `getMutations`, the `Mutation` record and its
//! `MutationKind`): the `eth_call` surface that carries every deny-set change
//! in order (ADR 011 § Following the mutation ledger). The node reads no
//! event log, so the bindings declare no event.
//!
//! The write + `getHashEntry` surface is mirrored for the cross-layer e2e
//! harness (`decdn-e2e`), which drives governance blacklist adds and reads
//! `addedAt` to time the compliance / slashability windows.

// The `sol!`-generated bindings include macro-emitted code that uses patterns
// workspace clippy denies (raw indexing into ABI fixed-size byte arrays,
// `unwrap` on infallible conversions). These allows scope the relaxation to
// this module only.
#[allow(
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::panic,
    clippy::unwrap_used,
    clippy::pub_underscore_fields,
    clippy::missing_docs_in_private_items,
    clippy::too_many_arguments,
    missing_debug_implementations,
    missing_docs,
    non_snake_case,
    non_camel_case_types
)]
mod sol_types {
    alloy::sol! {
        #[sol(rpc)]
        contract ContentBlacklist {
            /// Per-(region, hash) entry. `addedAt == 0` means "not blacklisted".
            ///
            /// MUST match `ContentBlacklist.HashEntry` field-for-field and in
            /// order — a static struct return is ABI-identical to the flattened
            /// tuple, so a missing field silently mis-decodes rather than
            /// failing loudly.
            ///
            /// `effectiveAt` (`addedAt + complianceWindow`, ADR 011 § Compliance
            /// Window) is the slashability boundary, NOT `addedAt`: an entry is
            /// unenforceable during the grace period a node needs to learn of it.
            /// `emergency` + `category` carry the auto-expiry term for entries
            /// added by the emergency multisig.
            struct HashEntry {
                uint64 addedAt;
                uint64 effectiveAt;
                bool emergency;
                uint8 category;
            }

            /// Region-scoped regional-body record (ADR 011 § Regional Governance
            /// Bodies). `body == address(0)` means no body is registered.
            struct RegionalBody {
                address body;
                uint64 suspendedAt;
                bool suspensionRatified;
            }

            // -----------------------------------------------------------------
            // View functions (consumed by the node runtime)
            // -----------------------------------------------------------------

            /// True iff `hash` is an enforceable blacklist entry in scope for
            /// `operator`: global ∪ current-region ∪ (ripening-window)
            /// previous-region, per ADR 030. The node's pre-cache spot check
            /// (ADR 011 § Following the mutation ledger).
            function isHashBlacklistedForOperator(bytes32 hash, address operator)
                external
                view
                returns (bool);

            /// Raw entry for `(region, hash)`. The node reads it at boot to give
            /// an emergency entry its local `expiresAt`; the e2e harness reads
            /// `addedAt` to time windows.
            function getHashEntry(bytes32 region, bytes32 hash)
                external
                view
                returns (HashEntry memory);

            /// True while `origin` is denied at the origin level, honouring
            /// emergency auto-expiry (a raw mapping read would not).
            ///
            /// The per-address boot reconcile relies on this predicate, which is usable
            /// because the deny-set is enumerable and has something to iterate over.
            ///
            /// This alone is NOT the address-liveness predicate: it reads only
            /// `_isOriginBlacklisted` and returns `false` for an OPERATOR-only
            /// entry (`addOperator` sets `isOperatorBlacklisted` and never touches
            /// the origin mapping). A boot reconcile of the `blacklistedAddresses`
            /// union MUST OR this with `isOperatorBlacklisted` — the same
            /// disjunction `ContentBlacklist._syncAddr` / `OriginAssignment` use —
            /// or it drops every voted-out operator (#1499).
            function isOriginBlacklisted(address origin) external view returns (bool);

            /// The operator half of the address deny-set (`addOperator` /
            /// `removeOperator`). Public auto-getter for the `mapping(address =>
            /// bool)`; there is no emergency auto-expiry on this leg, so — unlike
            /// [`isOriginBlacklisted`] — a raw read IS the live value. The boot
            /// reconcile ORs the two: `isOriginBlacklisted(a) ||
            /// isOperatorBlacklisted(a)`.
            function isOperatorBlacklisted(address operator) external view returns (bool);

            /// Every region key whose entries are in scope for `operator` right
            /// now: `GLOBAL` (always first), the declared region, and — while the
            /// ADR 030 ripening window is open — the previous one. One to three
            /// keys. Resolved on-chain through the same internal the slash-
            /// eligibility predicate uses, so the region packing and ripening
            /// math cannot drift between the two.
            function getScopeRegions(address operator) external view returns (bytes32[] memory);

            /// Number of entries indexed under `region`. Companion to
            /// `blacklistedHashes`; RAW membership, matching that view.
            function blacklistedHashCount(bytes32 region) external view returns (uint256);

            /// A page of `region`'s entry set. A page shorter than `limit` is the
            /// end of the set.
            ///
            /// Returns RAW membership — an emergency entry past its deadline is
            /// still listed, because filtering would put holes in a paginated
            /// view and dropping entries is the fail-open direction. Apply
            /// `isHashBlacklistedForOperator` (or `getHashEntry`) for liveness.
            ///
            /// Order is NOT stable across mutations (swap-and-pop removal), so
            /// every page — and the count it is checked against — MUST be read at
            /// one pinned block height, or a concurrent removal can move an
            /// unread element into an already-read slot and skip it.
            function blacklistedHashes(bytes32 region, uint256 offset, uint256 limit)
                external
                view
                returns (bytes32[] memory);

            /// Number of addresses denied at the origin or operator level.
            function blacklistedAddressCount() external view returns (uint256);

            /// A page of the UNION of the origin and operator deny lists — the
            /// same disjunction `OriginAssignment` evaluates per address, and the
            /// only readable source for that set. Same raw-membership and
            /// pinned-block caveats as `blacklistedHashes`.
            function blacklistedAddresses(uint256 offset, uint256 limit)
                external
                view
                returns (address[] memory);

            // -----------------------------------------------------------------
            // Write functions (governance — driven by the e2e harness)
            // -----------------------------------------------------------------

            /// Add `hash` to the global blacklist (`GOVERNANCE_ROLE`). `reason`
            /// is the free-form on-chain audit-trail note (DMCA/DSA notice id).
            function addHashGlobal(bytes32 hash, string reason) external;

            /// Add `hash` to `region`'s blacklist (`REGIONAL_BODY_ROLE`). `reason`
            /// is the free-form on-chain audit-trail note (DMCA/DSA notice id).
            function addHashRegional(bytes32 region, bytes32 hash, string reason) external;

            /// Remove `hash` from the global blacklist (`GOVERNANCE_ROLE`).
            function removeHashGlobal(bytes32 hash) external;

            /// Bind `body` to `region` and grant it `REGIONAL_BODY_ROLE`
            /// (`GOVERNANCE_ROLE`). `emergencyMultisig` is the
            /// `EMERGENCY_MULTISIG_ROLE` holder to check signer-disjointness
            /// against; it is verified to hold the role.
            function registerRegionalBody(bytes32 region, address body, address emergencyMultisig)
                external;

            /// The body registered for `region`, plus its suspension state.
            function getRegionalBody(bytes32 region) external view returns (RegionalBody memory);

            /// Grace (seconds) between a standard/regional add and the moment the
            /// entry becomes slashable (ADR 011 § Compliance Window).
            function complianceWindow() external view returns (uint64);

            // -----------------------------------------------------------------
            // Mutation ledger (ADR 011 § Following the mutation ledger)
            // -----------------------------------------------------------------

            /// What one ledger record changed. MUST match
            /// `ContentBlacklist.MutationKind` member-for-member and in order:
            /// the ABI carries the ordinal, so a reordering mis-decodes
            /// silently.
            enum MutationKind {
                HASH_ADD,
                HASH_EMERGENCY_ADD,
                HASH_RATIFY,
                HASH_REMOVE,
                HASH_EXPIRE,
                ORIGIN_SET,
                ORIGIN_CLEAR,
                ORIGIN_EMERGENCY_ADD,
                ORIGIN_EXPIRE,
                OPERATOR_ADD,
                OPERATOR_REMOVE,
                BODY_REGISTER,
                BODY_DEREGISTER,
                BODY_SUSPEND,
                BODY_SUSPENSION_RATIFY,
                BODY_UNSUSPEND,
                COMPLIANCE_WINDOW_SET,
                EMERGENCY_COMPLIANCE_WINDOW_SET
            }

            /// One append-only ledger record. `at` is the block timestamp of
            /// the change, `expiresAt` an emergency deadline (`0` when none),
            /// `region` the scope, and `key` the hash, the address (left-padded),
            /// or the window in seconds, by `kind`. MUST match
            /// `ContentBlacklist.Mutation` field-for-field and in order.
            struct Mutation {
                MutationKind kind;
                uint64 at;
                uint64 expiresAt;
                bytes32 region;
                bytes32 key;
            }

            /// Length of the mutation ledger. A node polls it and reads
            /// `getMutations` only when it moves.
            function mutationCount() external view returns (uint256);

            /// A page of the mutation ledger starting at `from`, at most
            /// `limit` long, in append order. A page shorter than `limit` is
            /// the end of the ledger. A record's index never changes.
            function getMutations(uint256 from, uint256 limit)
                external
                view
                returns (Mutation[] memory);

            /// Auto-expiry record of an emergency-added origin. `addedAt == 0`
            /// marks a permanent governance origin entry.
            struct EmergencyOrigin {
                uint64 addedAt;
                uint8 category;
            }

            /// The emergency record of `origin`, read at boot to give an
            /// emergency origin its local `expiresAt`.
            function getEmergencyOrigin(address origin)
                external
                view
                returns (EmergencyOrigin memory);

            /// Grace (seconds) between an emergency add and the moment the
            /// entry becomes slashable.
            function emergencyComplianceWindow() external view returns (uint64);
        }
    }
}

pub use sol_types::ContentBlacklist;
